import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for TreeTraversingParser.getLongValue().
 */
public class TreeTraversingParser_getLongValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }





    /**
     * Tests that getLongValue throws ClassCastException if the current node is not a NumericNode.
     * Note: The implementation performs (NumericNode) currentNumericNode().
     * If currentNumericNode() returns a non-numeric node (like TextNode), it will throw a ClassCastException.
     */
    @Test(expected = ClassCastException.class)
    public void testGetLongValue_NotANumericNode() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.put("text", "not a number");

        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // VALUE_STRING

        // This should trigger ClassCastException during the cast to NumericNode
        parser.getLongValue();
    }




}

