public class TreeTraversingParser_getLongValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }







    /**
     * Tests that getLongValue handles the maximum long value.
     */
    @Test
    public void testGetLongValue_MaxLong() throws IOException {
        ObjectNode root = mapper.createObjectNode();
        root.put("max", Long.MAX_VALUE);

        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken(); // FIELD_NAME
        parser.nextToken(); // VALUE_NUMBER_INT

        long result = parser.getLongValue();

        assertEquals(Long.MAX_VALUE, result);
    }


}

